class Solution {
public:
    vector<vector<long long>> splitPainting(vector<vector<int>>& segments) {
        map<int, long long> diff;
        for (auto& seg : segments) {
            diff[seg[0]] += seg[2];
            diff[seg[1]] -= seg[2];
        }

        vector<vector<long long>> result;
        long long sum = 0;
        int prev = -1;

        for (auto& [pos, delta] : diff) {
            if (prev != -1 && sum > 0) {
                result.push_back({(long long)prev, (long long)pos, sum});
            }
            sum += delta;
            prev = pos;
        }

        return result;
    }
};
